/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: isCatalogReviewLookup, lookupComparisonFor, catalogReviewLookupFileSet,
 *              catalogReviewPrimaryNames, catalogReviewFileEvidence, catalogReviewSearchedTitle,
 *              catalogReviewItunesSkippable, planCatalogReviewLookup, comparableSearchText,
 *              catalogReviewSearchTexts, catalogReviewTrackTitleSkip
 * Internal
 *   Types: ReviewSource
 *   Functions: isRecord, list, sha256, manifestSlots, shownPrimaryCredits, firstUsableCredit,
 *              catalogReviewTrackTitles, capturedDuration, catalogReviewPositionHints, submittedInput
 * @end-catalog */

/**
 * An existing-Album review's metadata lookup inputs, used where an import reads its uploaded files: the members it binds, the
 * ranking evidence of each member (with the positions its captured titles, else filenames, start with as pairing hints) and the
 * run plan from the Album's saved title and shown primary Artist names, with its saved Track titles (each with its own, else the
 * Album's, primary Artist name) for the optional Track-title searches, and whether a run may skip its iTunes fallback for a
 * fitting release of the searched title. For the review lookup view's timeline it also gives the texts a run can have searched
 * (only the review's own saved values and a submitted name) and why a run planned no Track-title search. A review has no
 * uploads, so its members are bound through its source check (readCatalogReviewSource), never through file identities. Pure: no
 * database and no review service, so metadataLookupRecord.ts imports it without a cycle. Every function is total on malformed
 * stored shapes.
 */
import { createHash } from 'node:crypto';
import { hasOwn, originKey } from '../import/adminImportDraft';
import { importDraftV2View } from '../import/adminImportDraftCompat';
import type { AdminImportDocument } from '../import/adminImportService';
import { lookupCandidateSource } from './lookupContract';
import { isPlaceholderCredit } from './lookupIdentifiers';
import { decoratedNameParts, titleWithoutTrailingCredit } from './lookupDecoratedNames';
import { isTrackTitleLookupQuery, planMetadataLookup, plannableSubmittedArtist, type LookupPlan } from './lookupQueryPlanner';
import type { LocalFileEvidence, LookupComparisonMode, RankedLookupCandidate } from './lookupRanking';
import type { LookupPositionHint } from './lookupSubset';
import { sameLookupTitle } from './lookupTitleNormalize';
import { distinctiveTrackTitles, trackTitlePositions, trackTitleSkipReason, type TrackTitleMember, type TrackTitleSkip } from './lookupTrackTitles';
import type { LookupFileIdentity, MetadataLookupInput, MetadataLookupSubmission } from './metadataLookupRecord';

type ReviewSource = Pick<AdminImportDocument, '_id' | 'purpose' | 'manifest' | 'draft' | 'draftOrigins' | 'catalogSource' | 'catalogEvidence' | 'catalogCapture'>;

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const sha256 = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
/** The manifest's slots in manifest order; a slot without a string ID is skipped. */
const manifestSlots = (doc: Pick<ReviewSource, 'manifest'>): { slotId: string }[] =>
    list(isRecord(doc.manifest) ? doc.manifest.files : null).filter((file): file is { slotId: string } => isRecord(file) && typeof file.slotId === 'string');

/** Whether a lookup document is an existing-Album review, compared in subset mode. */
export const isCatalogReviewLookup = (doc: Pick<AdminImportDocument, 'purpose'>): boolean => doc.purpose === 'catalogReview';
/** The ranking comparison of a lookup document: subset for a review, exact for an import. */
export const lookupComparisonFor = (doc: Pick<AdminImportDocument, 'purpose'>): LookupComparisonMode => isCatalogReviewLookup(doc) ? 'subset' : 'exact';

/**
 * The members a review run binds: one identity per manifest slot with no upload intent or bytes, so a file-set check never finds
 * one stale, and a digest of each source track's ID and media evidence. Always complete: a review never waits for an upload.
 */
export function catalogReviewLookupFileSet(doc: Pick<ReviewSource, 'manifest' | 'catalogSource' | 'catalogEvidence'>): { files: LookupFileIdentity[]; complete: boolean; digest: string } {
    const files = manifestSlots(doc).map(file => ({ slotId: file.slotId, operationId: null, sha256: null }));
    const evidence = isRecord(doc.catalogEvidence) ? doc.catalogEvidence : {};
    const members = list(isRecord(doc.catalogSource) ? doc.catalogSource.tracks : null).filter((track): track is { id: string } => isRecord(track) && typeof track.id === 'string')
        .map(track => [track.id, hasOwn(evidence, track.id) && typeof evidence[track.id] === 'string' ? evidence[track.id] : null]);
    return { files, complete: true, digest: sha256({ catalogReview: true, members }) };
}

/**
 * Shown primary Artist Credits of captured `credits`: primary Artist Credits that name a draft entry and a ready record with a
 * non-empty name, in stored order, a name repeated in another case once, each with its record's MusicBrainz ID as captured.
 */
function shownPrimaryCredits(credits: unknown): { name: string; musicBrainzId: unknown }[] {
    const shown: { name: string; musicBrainzId: unknown }[] = [], seen = new Set<string>();
    for (const credit of list(credits)) {
        if (!isRecord(credit) || credit.subjectType !== 'artist' || credit.role !== 'primary' || typeof credit.entryKey !== 'string' || !isRecord(credit.subject)) continue;
        const name = typeof credit.subject.name === 'string' ? credit.subject.name.trim() : '';
        const folded = name.normalize('NFC').toLowerCase();
        if (!name || seen.has(folded)) continue;
        seen.add(folded); shown.push({ name, musicBrainzId: credit.subject.musicBrainzId });
    }
    return shown;
}

/**
 * The names of the Album's shown primary Artist Credits as the review captured them (shownPrimaryCredits). Empty without a
 * readable capture (a review not yet admitted to lookup).
 */
export function catalogReviewPrimaryNames(doc: Pick<ReviewSource, 'catalogCapture'>): string[] {
    const capture: unknown = doc.catalogCapture, album = isRecord(capture) ? capture.album : null;
    return shownPrimaryCredits(isRecord(album) ? album.credits : null).map(credit => credit.name);
}

/** The first of shown primary Artist Credits that is no placeholder by name or MusicBrainz ID; null without one. */
const firstUsableCredit = (credits: unknown): string | null =>
    shownPrimaryCredits(credits).find(credit => !isPlaceholderCredit(credit.name, credit.musicBrainzId))?.name ?? null;

/**
 * Each source track's saved title as the review captured it from the catalog (never a draft value), its retained original
 * filename (read only to skip a title equal to it) and its credit: its own first shown primary Artist name that is no placeholder
 * by name or MusicBrainz ID, else the Album's first such name, in source order.
 */
function catalogReviewTrackTitles(doc: Pick<ReviewSource, 'catalogSource' | 'catalogCapture'>): TrackTitleMember[] {
    const capture: unknown = doc.catalogCapture, members = list(isRecord(capture) ? capture.members : null);
    const album = firstUsableCredit(isRecord(capture) && isRecord(capture.album) ? capture.album.credits : null);
    return list(isRecord(doc.catalogSource) ? doc.catalogSource.tracks : null).filter(isRecord).map(track => {
        const member = members.find(item => isRecord(item) && typeof track.slotId === 'string' && item.slotId === track.slotId);
        return { title: track.title, originalFileName: track.originalFileName, artist: firstUsableCredit(isRecord(member) ? member.credits : null) ?? album };
    });
}

/** A member's captured duration: exact milliseconds (precision 0) or a legacy whole-second value (precision 1000); null when unknown. */
function capturedDuration(member: unknown): { durationMs: number; durationPrecisionMs: 0 | 1000 } | null {
    const duration = isRecord(member) && isRecord(member.duration) ? member.duration : null;
    const durationMs = duration?.durationMs;
    if (!Number.isSafeInteger(durationMs) || (durationMs as number) <= 0) return null;
    return { durationMs: durationMs as number, durationPrecisionMs: duration!.durationPrecisionMs === 1000 ? 1000 : 0 };
}

/**
 * Each member's position hint by slot: the positions every captured saved title starts with when they count as for Track-title
 * searches (trackTitlePositions), else those of every retained original filename read the same way; none unless every manifest
 * member has one. Read only from the capture (`catalogSource`, Album order), never a draft value, and never sent.
 */
function catalogReviewPositionHints(doc: Pick<ReviewSource, 'manifest' | 'catalogSource'>): Map<string, LookupPositionHint> {
    const tracks = list(isRecord(doc.catalogSource) ? doc.catalogSource.tracks : null).filter(isRecord);
    const read = (field: 'title' | 'originalFileName', from: LookupPositionHint['from']) => {
        const positions = trackTitlePositions(tracks.map(track => track[field]));
        return positions ? new Map(tracks.flatMap((track, index) => typeof track.slotId === 'string'
            ? [[track.slotId, { discNumber: positions[index].discNumber, trackNumber: positions[index].trackNumber, from }] as const] : [])) : null;
    };
    const hints = read('title', 'title') ?? read('originalFileName', 'fileName');
    return hints && manifestSlots(doc).every(slot => hints.has(slot.slotId)) ? hints : new Map();
}

/**
 * Ranking evidence per member in manifest order: the captured duration (unknown without one), the member's own Disc and Track
 * Number from the draft (captured from the catalog or saved by an administrator; a number whose origin is automatic, which lookup
 * wrote, is unknown), the shown primary Artist names as every member's artist tags and no identifiers; and, when every captured
 * title (else retained filename) starts with a counting position, that position as a pairing hint (catalogReviewPositionHints),
 * apart from the own numbers. Without hints the key is absent, so such evidence is unchanged.
 */
export function catalogReviewFileEvidence(doc: ReviewSource): LocalFileEvidence[] {
    const slots = manifestSlots(doc), names = catalogReviewPrimaryNames(doc), hints = catalogReviewPositionHints(doc);
    const capture: unknown = doc.catalogCapture, members = list(isRecord(capture) ? capture.members : null);
    const origins = isRecord(doc.draftOrigins) ? doc.draftOrigins : {};
    let tracks: { slotId: string; discNumber: number | null; trackNumber: number | null }[] = [];
    try {
        tracks = importDraftV2View(doc.draft, { rootLabel: '', files: slots.map(slot => ({ slotId: slot.slotId, filename: '', relativePath: '', byteLength: null })) },
            doc._id.toHexString()).tracks;
    } catch { tracks = []; }
    const own = (slotId: string, field: 'discNumber' | 'trackNumber', value: number | null | undefined) =>
        hasOwn(origins, originKey(`tracks.${slotId}.${field}`)) && origins[originKey(`tracks.${slotId}.${field}`)] === 'automatic' ? null : value ?? null;
    return slots.map(({ slotId }, order) => {
        const duration = capturedDuration(members.find(member => isRecord(member) && member.slotId === slotId));
        const track = tracks.find(item => item.slotId === slotId);
        return {
            slotId, order, durationMs: duration?.durationMs ?? null, durationPrecisionMs: duration?.durationPrecisionMs ?? 0,
            discNumber: own(slotId, 'discNumber', track?.discNumber), trackNumber: own(slotId, 'trackNumber', track?.trackNumber),
            artistTags: [...names], identifiers: { releaseId: null, barcode: null, catalogNumber: null },
            ...(hints.has(slotId) ? { positionHint: { ...hints.get(slotId)! } } : {})
        };
    });
}

/**
 * The Album title a review run searched: the captured saved title of its catalog run, or the text of a run submitted as an Album
 * name; null for a submitted song name or any other input.
 */
export function catalogReviewSearchedTitle(doc: Pick<ReviewSource, 'catalogSource'>, input: unknown): string | null {
    const value = isRecord(input) ? input : null, submitted = value && isRecord(value.submitted) ? value.submitted : null;
    if (value?.trigger === 'submitted') return submitted?.kind === 'album' && typeof submitted.text === 'string' ? submitted.text : null;
    if (value?.trigger !== 'catalog') return null;
    const album = isRecord(doc.catalogSource) && isRecord(doc.catalogSource.album) ? doc.catalogSource.album.title : null;
    return typeof album === 'string' ? album : null;
}

/**
 * Whether a review run that found no matching group may skip its iTunes fallback: a MusicBrainz candidate not first found by a
 * Track title (`byTrackTitle` false) is unverified while the Album has members (its pairing not single, or a duration unknown),
 * its credit agrees with the Album's shown primary Artist names (`artistMismatch` false while there is at least one name and none
 * is a placeholder credit by name or MusicBrainz ID, so the agreement is never a placeholder's: every member's artist tags are
 * those names, and no alias or iTunes localized name is known before this decision, so only a direct or decorated agreement
 * counts), and its release title equals the searched title (catalogReviewSearchedTitle) as sameLookupTitle compares them with
 * those names. Pure.
 */
export function catalogReviewItunesSkippable(doc: ReviewSource, input: unknown, candidates: readonly RankedLookupCandidate[], byTrackTitle: (key: string) => boolean): boolean {
    const searched = catalogReviewSearchedTitle(doc, input), names = catalogReviewPrimaryNames(doc);
    const credits = shownPrimaryCredits(isRecord(doc.catalogCapture) && isRecord(doc.catalogCapture.album) ? doc.catalogCapture.album.credits : null);
    if (searched === null || !names.length || credits.some(credit => isPlaceholderCredit(credit.name, credit.musicBrainzId))) return false;
    // A malformed entry has no MusicBrainz key, so it never counts.
    return (Array.isArray(candidates) ? candidates : []).some(candidate => lookupCandidateSource(candidate?.key) === 'musicbrainz'
        && !byTrackTitle(candidate.key) && candidate.status === 'unverified' && (candidate.comparison?.trackCount?.local ?? 0) > 0
        && candidate.artistMismatch === false && sameLookupTitle(candidate.proposal?.albumTitle, searched, names));
}

/**
 * A review run's input and plan: the Album's saved title as the review captured it, with its shown primary Artist names as the
 * credited artists (`catalog`), or with `submitted` the submitted text planned with those names, or with its Artist name in their
 * place (kept only when it can be sent). Its distinctive saved Track titles plan the optional Track-title searches (only into the
 * queries, never the input); file names, folders, labels and identifiers are never sent.
 */
export function planCatalogReviewLookup(doc: ReviewSource, options: { submitted?: MetadataLookupSubmission } = {}): { input: MetadataLookupInput; plan: LookupPlan } {
    const credited = catalogReviewPrimaryNames(doc), fileCount = manifestSlots(doc).length;
    const album = isRecord(doc.catalogSource) && isRecord(doc.catalogSource.album) && typeof doc.catalogSource.album.title === 'string' ? doc.catalogSource.album.title : null;
    const trackTitles = (submittedText?: string) => distinctiveTrackTitles(catalogReviewTrackTitles(doc), { albumTitle: album, submittedText });
    if (options.submitted) {
        const submitted: MetadataLookupSubmission = { kind: options.submitted.kind, text: options.submitted.text,
            ...(plannableSubmittedArtist(options.submitted.artist) ? { artist: options.submitted.artist } : {}) };
        return { input: { trigger: 'submitted', submitted },
            plan: planMetadataLookup({ trigger: 'submitted', submitted, credited, fileCount, trackTitles: trackTitles(submitted.text) }) };
    }
    return { input: { trigger: 'catalog', submitted: null },
        plan: planMetadataLookup({ trigger: 'catalog', tags: { album, albumArtist: null, title: null, artist: null }, credited, fileCount, trackTitles: trackTitles() }) };
}

/** A search text as the lookup view compares it with the review's own texts: NFKC, whitespace collapsed and trimmed; null for a non-string or over 1000 characters. */
export const comparableSearchText = (value: unknown): string | null =>
    typeof value === 'string' && value.length <= 1000 ? value.normalize('NFKC').replace(/\s+/gu, ' ').trim() || null : null;

/** A run input's submitted name and kind, with any Artist name, when it is a submitted run's; else null. */
function submittedInput(input: unknown): MetadataLookupSubmission | null {
    const value = isRecord(input) ? input : null, submitted = value?.trigger === 'submitted' && isRecord(value.submitted) ? value.submitted : null;
    if (!submitted || (submitted.kind !== 'album' && submitted.kind !== 'song') || typeof submitted.text !== 'string') return null;
    return { kind: submitted.kind, text: submitted.text, ...(typeof submitted.artist === 'string' ? { artist: submitted.artist } : {}) };
}

/**
 * The texts a review run can have searched, as comparableSearchText compares them: the Album's captured saved title and that title
 * without a trailing credit, the shown primary Artist names and each member's credited name (its own first usable primary Artist
 * name, else the Album's) with a decorated name's first part, the captured Track titles the picker keeps for the run's input, and
 * a submitted name and Artist name. The lookup view shows a stored search text only when it is one of these, so it never shows a
 * filename, folder name, label or identifier.
 */
export function catalogReviewSearchTexts(doc: ReviewSource, input: unknown): ReadonlySet<string> {
    const names = catalogReviewPrimaryNames(doc), members = catalogReviewTrackTitles(doc), submitted = submittedInput(input);
    const album = isRecord(doc.catalogSource) && isRecord(doc.catalogSource.album) && typeof doc.catalogSource.album.title === 'string' ? doc.catalogSource.album.title : null;
    const credited = [...names, ...members.map(member => member.artist), submitted?.artist].filter((name): name is string => typeof name === 'string');
    const texts = [album, titleWithoutTrailingCredit(album, names), submitted?.text, ...credited.flatMap(name => [name, decoratedNameParts(name)?.[0]]),
        ...distinctiveTrackTitles(members, { albumTitle: album, submittedText: submitted?.text }).map(title => title.text)];
    return new Set(texts.map(comparableSearchText).filter((text): text is string => text !== null));
}

/**
 * Why a review run planned no Track-title search although the Album has members: the reason the picker kept none of its captured
 * titles for the run's input (trackTitleSkipReason), else `noneDistinct` when the plan for that input still holds none, as each
 * kept title was too light to search without an Artist name. Null for an Album without members, an input that is neither the
 * catalog run's nor a submitted name, or when the plan for that input holds a Track-title search (the run was planned by an
 * earlier release, so this release cannot say why it holds none).
 */
export function catalogReviewTrackTitleSkip(doc: ReviewSource, input: unknown): TrackTitleSkip | null {
    const submitted = submittedInput(input), members = catalogReviewTrackTitles(doc);
    if (!members.length || (!submitted && !(isRecord(input) && input.trigger === 'catalog'))) return null;
    const album = isRecord(doc.catalogSource) && isRecord(doc.catalogSource.album) && typeof doc.catalogSource.album.title === 'string' ? doc.catalogSource.album.title : null;
    const reason = trackTitleSkipReason(members, { albumTitle: album, submittedText: submitted?.text });
    if (reason) return reason;
    const { plan } = planCatalogReviewLookup(doc, submitted ? { submitted } : {});
    return plan.queries.length && !plan.queries.some(isTrackTitleLookupQuery) ? 'noneDistinct' : null;
}
